import React from 'react';
import { Link } from 'react-router-dom';
//estilos
import "../../components/cliente.css";
//imagenes

// header y footer
import Header from '../../components/Header_c.jsx'; 
import Footer from '../../components/Footer.jsx';

const PedidosPersonalizados = () => {
    return (
        <div className="app-container">

            <Header />

            <main className="pedidos-personalizados">
                <h2>Pedidos personalizados</h2>
                <p>Diseña tus pedidos a tu medidia</p>

                <div className="productos">
                    {/* Opción 1: Sábanas */}
                    <div className="producto">
                        <img src="../imagenes/sabana.webp" alt="Sabanas" />
                        <Link to="/personalizar_sabana" className="boton-producto">Sábanas</Link>
                    </div>

                    {/* Opción 2: Cubrelechos */}
                    <div className="producto">
                        <img src="../imagenes/cubrelecho.webp" alt="Cubrelechos" />
                        <Link to="/personalizar_cubrelecho.html" className="boton-producto">Cubrelechos</Link>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default PedidosPersonalizados;
